DELIMITER ;;

CREATE TRIGGER `after_santri_status_update` AFTER UPDATE ON `sch__santri` FOR EACH ROW
BEGIN
  -- cek kalau kolom status berubah jadi -1
  IF NEW.status = '-1' AND OLD.status <> NEW.status THEN
    DELETE n
      FROM sch_aka_nilai n
      INNER JOIN sch_aka_pembagian_mapel pm ON pm.id=n.id_pembagian_mapel
      INNER JOIN sch__semester s ON s.id=pm.id_semester
      WHERE n.id_santri = NEW.id 
        AND (pm.lock_nilai_harian = '0' OR pm.lock_uts='1' OR pm.lock_uas='1')
        AND s.current='1';
  END IF;
END;;

DELIMITER ;

